\label{thm:local}
For every $\varepsilon>0$ and every ball $B_R\subset\mathbb{R}^n$, $R\ge1$,
\begin{equation}\label{eq:local}
 \|Ef\|_{L^{p_c(n)}(B_R)}^{p_c(n)}
 \lesssim_{n,\varepsilon}R^\varepsilon
 \|f\|_2^2\mathcal M_R(f)^{p_c(n)-2}.
\end{equation}

\label{thm:incidence}
Let $n\ge4$, $d=n-2$, and let $\mathcal T$ be a family of null $\delta$-tubes as above, with at most $m$ positions per direction. Suppose their shadings are $\lambda$-dense and $(a,b)$-two-ends. Set
\[
 E_Y=\bigcup_{T\in\mathcal T}Y(T),\qquad
 S_Y=\sum_{T\in\mathcal T}|Y(T)|.
\]
Then for every $\varepsilon>0$,
\begin{equation}\label{eq:incidence}
 \frac{S_Y}{|E_Y|}
 \lesssim_{n,\varepsilon,a,b,C_0}
 \delta^{-\varepsilon-da/2}
       (m/\lambda)^{1/2}\delta^{-(d-1)/2}.
\end{equation}

\label{lem:remote}
Fix a stem $T_0$. Let $\mathcal H$ be tubes meeting $T_0$ whose parameters satisfy $|u-u_0|\sim\rho$, with $\delta\lesssim\rho\lesssim1$. For each $T\in\mathcal H$, choose a contact time $\tau_T$. If $\delta\le h\le1$, then
\begin{equation}\label{eq:remote}
 \sup_z\sum_{T\in\mathcal H}
 \mathbf1_{T\cap\{|t-\tau_T|\ge h\}}(z)
 \lesssim \rho^{-1}h^{-d}.
\end{equation}
Also,
\begin{equation}\label{eq:pair}
 |T\cap T_0|\lesssim\delta^n/\rho.
\end{equation}

\label{prop:KT}
Under the hypotheses of Theorem~\ref{thm:incidence}, suppose $\lambda\ge\delta^{1/4}$ and let $D$ be the number of occupied directions. Then, suppressing an arbitrarily small loss and the two-ends loss,
\begin{equation}\label{eq:projected}
 \frac{S_Y}{|E_Y|}\lessapprox
       m\lambda^{-(2n+5)/7}D^{3/7}
 \le m\lambda^{-(2n+5)/7}\delta^{-3(n-2)/7}.
\end{equation}
